using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PrecisionExchangeActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PrecisionExchangeActionCustomDescription", order = 0)]
public class PrecisionExchangeActionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return (battleAction as PrecisionExchangeAction).PrecisionExchangeLogicAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
	}
}
